  A.TRACES = TR;
  const T0 = TR || { mot: { lettres: ['M0,0 H80 V100 H0 Z'], boite: [0, 0, 80, 100] }, symbole: { pieces: ['M0,0 H80 V100 H0 Z'], boite: [0, 0, 80, 100] }, descripteur: { lignes: [], boite: [0, 0, 1, 1] }, boite: [0, 0, 80, 100], traits: [], epaisseur: 10 };
