  A.LOCKUP = { lines: [], x: 0, size: 46, baselines: [], tracking: 0, box: [tb[0] - 6, tb[1] - 6, tb[2] + 12, tb[3] + 12] };
  A.FONTS = { nom: 'Nunito', variable: '@fontsource-variable/nunito/files/nunito-latin-wght-normal.woff2', graisses: { Medium: 500, Bold: 700, ExtraBold: 800, Black: 900 }, logo: 'ExtraBold',
    chiffres: { nom: 'Geist Mono', variable: '@fontsource-variable/geist-mono/files/geist-mono-latin-wght-normal.woff2', graisses: { Regular: 400, Medium: 500, SemiBold: 600 } } };
