  A.court = (fill, attrs = '') => { const f = fill ? [col(fill), col(fill)] : [C.vermillon, C.ocre], b = [tb[0] - 6, tb[1] - 6, tb[2] + 12, tb[3] + 12];
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${vb(b)}" ${attrs}><path fill="${f[0]}" d="${A.wordPath()}"/><path fill="${f[1]}" d="${A.symbolPath()}"/></svg>`; };
