  /* ---------- La marge du métier ---------- */
  /* Un montant en euros, à l'euro près, espaces fines insécables. euro(15628761) → « 15 628 761 € » */
  const milliers = (n) => String(Math.round(Math.abs(n))).replace(/\B(?=(\d{3})+(?!\d))/g, FINE);
  A.nombre = (n) => (n < 0 ? '−' : '') + milliers(n);
