  A.euroK = (n) => { const a = Math.abs(n); if (a >= 1e6) return `${(n / 1e6).toFixed(a >= 1e7 ? 1 : 2).replace('.', ',')}${NB}M€`; if (a >= 1e3) return `${Math.round(n / 1e3)}${NB}k€`; return A.euro(n); };
