    for (let g = 0; g <= grille; g++) { const y = r1(mt + H - (g / grille) * H); s += `<path d="M${ml},${y} H${w - mr}" stroke="${col(cTexte)}" stroke-opacity="${g ? 0.08 : 0.2}" stroke-width="1"${g ? ' stroke-dasharray="2 5"' : ''}/><text x="${ml - 10}" y="${y + 3.5}" text-anchor="end" font-family="Geist Mono, monospace" font-size="10" fill="${col(cTexte)}" fill-opacity=".5">${g ? unite((g / grille) * M) : '0'}</text>`; }
